rule "UniFi - normalize severity to GIM"
when
  has_field("unifi_severity")
then
  let level = lookup_value("unifi_gim_severity_level", to_string($message.unifi_severity));
  let name = lookup_value("unifi_gim_severity", to_string($message.unifi_severity));
  set_field("vendor_event_severity", to_string($message.unifi_severity));
  set_field("event_severity", to_string(name));
  set_field("event_severity_level", to_long(level));
end

rule "UniFi - detect mixed format"
when
  has_field("unifi_ingest") && to_bool($message.unifi_ingest)
then
  set_field("unifi_schema_version", "gim-7.1");
  set_field("unifi_integration_version", "0.1.0");
  set_field("full_message", to_string($message.message));
  let cef = regex(pattern: "(?:^|\\s)(CEF:\\d+\\|Ubiquiti\\|UniFi Network\\|.*)$", value: to_string($message.message));
  let device = regex(pattern: "^[^ ]+ [0-9A-Fa-f]{12},.+-\\d+\\.\\d+\\.\\d+\\+\\d+:", value: to_string($message.message));
  set_field("unifi_log_format", if(cef.matches, "cef", if(device.matches, "syslog", "unknown")));
  set_field("unifi_parse_status", if(cef.matches || device.matches, "detected", "malformed"));
end

rule "UniFi - parse device syslog header"
when
  has_field("unifi_log_format") && to_string($message.unifi_log_format) == "syslog"
then
  let header = grok(
    pattern: "%{UNIFI_DEVICE_HEADER}",
    value: to_string($message.message),
    only_named_captures: true
  );
  set_fields(header);
  set_field("event_source_product", "unifi_device");
  set_field("event_source", to_string(header["host_name"]));
  set_field("host_mac", to_string(header["unifi_device_mac"]));
  set_field("host_device_vendor", "Ubiquiti");
  set_field("host_device_model", to_string(header["unifi_device_model"]));
  set_field("host_os_version", to_string(header["unifi_device_version"]));
  set_field("unifi_parse_status", "unsupported");
end

rule "UniFi - normalize CEF client events"
when
  has_field("unifi_log_format") && to_string($message.unifi_log_format) == "cef"
then
  set_field("event_observer_hostname", to_string($message.UNIFIhost));
  set_field("event_reporter", to_string($message.UNIFIhost));
  set_field("event_source", to_string($message.UNIFIhost));
  set_field("unifi_site_code", to_string($message.UNIFIsite));
  set_field("source_ip", to_ip($message.UNIFIclientIp));
  set_field("source_mac", lowercase(to_string($message.UNIFIclientMac)));
  set_field("network_name", to_string($message.UNIFInetworkName));
  set_field("network_cidr", to_string($message.UNIFInetworkSubnet));
  set_field("network_vlan", to_long($message.UNIFInetworkVlan));
  set_field("gim_event_type_code", 129999);
  set_field("gim_event_category", "network");
  set_field("gim_event_subcategory", "network.default");
  set_field("gim_event_type", "network message");
  let connected = to_string($message.device_event_class_id) == "403";
  let disconnected = to_string($message.device_event_class_id) == "404";
  set_field("event_action", if(connected, "connected", if(disconnected, "disconnected", "unknown")));
  set_field("unifi_event_type", if(connected, "network.client.connected", if(disconnected, "network.client.disconnected", "unknown")));
  set_field("event_code", to_long($message.device_event_class_id));
  set_field("event_id", to_string($message.device_event_class_id));
  set_field("unifi_severity", lookup_value("unifi_cef_severity", to_string($message.severity)));
end

rule "UniFi - normalize device syslog families"
when
  has_field("unifi_vendor_message")
then
  let text = to_string($message.unifi_vendor_message);
  let link = regex(pattern: "Port (?<port>\\d+) link (?<state>up|down)$", value: text);
  let stp = regex(pattern: "Port (?<port>\\d+) moving from (?<previous>[A-Za-z]+) to (?<state>[A-Za-z]+)$", value: text);
  let wlan = regex(pattern: "(?<interface>[^:]+): STA (?<client>[0-9A-Fa-f:]{17}) IEEE 802\\.11: (?<state>associated|disassociated)$", value: text);
  let mesh = contains(value: text, search: "ace_reporter.mesh_halt_timeout(): Mesh halt expired");
  let reboot = contains(value: text, search: "ace_reporter.reporter_handle_response_json(): [reboot] reboot");
  let known = link.matches || stp.matches || wlan.matches || mesh || reboot;
  set_field("unifi_parse_status", if(known, "parsed", "unsupported"));
  set_field("unifi_switch_port", if(link.matches, to_long(link["port"]), if(stp.matches, to_long(stp["port"]), 0)));
  set_field("source_mac", if(wlan.matches, lowercase(to_string(wlan["client"])), ""));
  set_field("destination_mac", if(wlan.matches, lowercase(to_string($message.host_mac)), ""));
  set_field("destination_hostname", if(wlan.matches, to_string($message.host_name), ""));
  set_field("unifi_wlan_interface", if(wlan.matches, to_string(wlan["interface"]), ""));
  set_field("unifi_mesh_timeout", mesh);
  set_field("event_action", if(link.matches, lowercase(to_string(link["state"])), if(stp.matches, lowercase(to_string(stp["state"])), if(wlan.matches, if(to_string(wlan["state"]) == "associated", "connected", "disconnected"), if(mesh, "timeout", if(reboot, "reboot", "unknown"))))));
  set_field("unifi_event_type", if(link.matches, concat("network.port.", lowercase(to_string(link["state"]))), if(stp.matches, concat("network.port.", lowercase(to_string(stp["state"]))), if(wlan.matches, if(to_string(wlan["state"]) == "associated", "network.client.connected", "network.client.disconnected"), if(mesh, "wireless.mesh.timeout", if(reboot, "device.reboot", "unknown"))))));
end

rule "UniFi - parse CEF"
when
  has_field("unifi_log_format") && to_string($message.unifi_log_format) == "cef"
then
  let capture = regex(pattern: "(CEF:\\d+\\|Ubiquiti\\|UniFi Network\\|.*)$", value: to_string($message.message));
  let cef = parse_cef(to_string(capture["0"]), use_full_names: true);
  set_fields(to_map(cef));
  set_field("event_source_product", "unifi_network");
  set_field("vendor_name", "Ubiquiti");
  set_field("vendor_product", "UniFi Network");
  set_field("unifi_parse_status", "parsed");
end
